        if len(set(g[c]))==1 and g[c][0]!=g[0][0]: sep=c
    sb=[c for c in range(H) if len(set(g[c]))==1 and c!=sep]
    sc=[c for c in range(W) if len(set(r[c] for r in g))==1 and c!=sep]
    hblocks=[]; start=0
    for s in sb+[H]:
        if s-start>1: hblocks.append((start,s-1)); 
        start=s+1
    wblocks=[]; start=0
    for s in sc+[W]:
        if s-start>1: wblocks.append((start,s-1)); start=s+1
    out=[]
    for a,b in hblocks:
        row=[]
        for c,d in wblocks:
            blk=[r[c:d+1] for r in g[a:b+1]]
            cnt={}
            for r2 in blk:
                for v in r2: cnt[v]=cnt.get(v,0)+1
            v,_=cnt.most_common(1)[0]
            anom=sum(1 for r2 in blk for u in r2 if u!=v)
            row.append(1 if anom>=2 else v)
